use sha2 :: { Sha256 , Digest } ; use std :: time :: Instant ; use hex_literal :: * ; pub fn hash_from_prev (timestamp : i64 , data_hash : [u8 ; 32] , old_hash : [u8 ; 32]) -> [u8 ; 32] { let timestamp_hash = Sha256 :: digest (timestamp . to_be_bytes ()) ; * Sha256 :: digest ([* timestamp_hash . as_ref () , data_hash , old_hash] . concat ()) . as_ref () } fn main () { println ! ("Hello, world!") ; let cur = Instant :: now () ; let fake = 323212_i64 ; let data_hash = hex ! ("8b7df143d91c716ecfa5fc1730022f6b421b05cedee8fd52b1fc65a96030ad52") ; let old_hash = hex ! ("cba06b5736faf67e54b07b561eae94395e774c517a7d910a54369e1263ccfbd4") ; let new_hash = hash_from_prev (fake , data_hash , old_hash) ; println ! ("{:#?}" , new_hash) ; }